Let's start with the Redux setup.

### Store and Redux Toolkit Setup

Create a new file `store.js` with the following content. This will set up a basic Redux store with Redux Toolkit.

```javascript
import { configureStore } from '@reduxjs/toolkit';
import cartReducer from './cartSlice';

const store = configureStore({
  reducer: {
    cart: cartReducer,
  },
});

export default store;
```

Create a new file `cartSlice.js` with the following content. This will define the reducer and actions for the cart.

```javascript
import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
  total: 0,
};

export const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem(state, action) {
      const existingItem = state.items.find(
        (item) => item.product.id === action.payload.product.id
      );

      if (existingItem) {
        existingItem.quantity++;
      } else {
        state.items.push({
          product: action.payload.product,
          quantity: 1,
        });
      }

      state.total += action.payload.product.price;
    },
    removeItem(state, action) {
      const index = state.items.findIndex(
        (item) => item.product.id === action.payload.product.id
      );

      if (index >= 0) {
        state.items.splice(index, 1);
        state.total -= state.items[index].product.price * state.items[index].quantity;
      }
    },
  },
});

export const { addItem, removeItem } = cartSlice.actions;

export default cartSlice.reducer;
```

