This is the reducer where we manage our cart state:

```javascript
import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
  total: 0,
  loading: false,
};

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem(state, action) {
      const { id, price, name } = action.payload;
      const existingItem = state.items.find((item) => item.id === id);
      if (existingItem) {
        existingItem.quantity += 1;
      } else {
        state.items.push({ id, price, name, quantity: 1 });
      }
      state.total += price;
    },
    removeItem(state, action) {
      const { id } = action.payload;
      const existingItem = state.items.find((item) => item.id === id);
      if (existingItem && existingItem.quantity > 1) {
        existingItem.quantity -= 1;
      } else {
        state.items = state.items.filter((item) => item.id!== id);
      }
      state.total -= existingItem.price;
    },
    clearCart(state) {
      state.items = [];
      state.total = 0;
    },
    setQuantity(state, action) {
      const { id, quantity } = action.payload;
      const existingItem = state.items.find((item) => item.id === id);
      if (existingItem) {
        existingItem.quantity = quantity;
        state.total -= existingItem.price * (existingItem.quantity - quantity);
        state.total += existingItem.price * quantity;
      }
    },
  },
});

export const { addItem, removeItem, clearCart, setQuantity } = cartSlice.actions;
export default cartSlice.reducer;
```

